public class ThreadDemo extends Thread {
    public static void main(String[] args) throws InterruptedException {
        ThreadDemo t1 = new ThreadDemo();
        ThreadDemo t2 = new ThreadDemo();
        t1.start();

        // starts the 2nd thread after 2 seconds, or sooner if t1 already finished
        t1.join(2000);
        t2.start();

        // now wait for both threads to fully finish
        t1.join();
        t2.join();

        System.out.println("Thread-0 is alive: " + t1.isAlive());
        System.out.println("Thread-1 is alive: " + t2.isAlive());
    }

    public void run() {
        System.out.println(Thread.currentThread().getName() + " is running.");
        try {
            Thread.sleep(3000); // suspends this thread for 3 seconds
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
        System.out.println(Thread.currentThread().getName() + " has ended.");
    }
}
// Output:
// Thread-0 is running.
// Thread-1 is running.
// Thread-0 has ended.
// Thread-1 has ended.
// Thread-0 is alive: false
// Thread-1 is alive: false
